#  인용 = [@key](manifest key) 또는 [@web:...]. 단독 저자 → 1인칭 금지. 미국식 철자. 결과 절에 해석 금지.
from numbers_htn import load, ROB, RS
import os, pandas as pd
LO = pd.read_csv(os.path.join(RS, "S41_leaveout_ranges.csv")).set_index(["set", "cov"])
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]
    return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}-{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}-{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
NC = lambda v: (N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"])
SC = lambda s, v: N["sens_main"][s][v]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    return ", ".join(f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n])
TITLE = "Within-district growth in public sports facilities tracked slightly less hypertension care across Korea over fourteen years of nationwide claims"
RUNNING = "Sports facilities and hypertension care"
KEYWORDS = "built environment; physical activity; sports facilities; blood pressure; spatiotemporal analysis; Bayesian disease mapping; Republic of Korea"
HOT_KH = {k: int(N["mv"][k]["n_specs"]) for k in ROB}
_R14 = N["ret14"]

METHODS = [
("Data sources and outcome",
 f"This ecological study used annual numbers of people treated for hypertension (International Classification of Diseases, 10th revision [ICD-10] codes I10-I15 as the principal diagnosis) from the Regional Medical Care Utilization Statistics of the National Health Insurance Service, 2011-2024 [@web:nhis2026regional]. The statistics cover National Health Insurance and Medical Aid beneficiaries, count care by date of service in all care settings, and attribute each person to the district of residence rather than to the treating facility. Each count is the number of unique persons with at least one claim with hypertension as the principal diagnosis in a year and therefore reflects people under care for hypertension, which depends on prevalence, awareness, and treatment together; hypertension recorded only as a secondary diagnosis is not counted. Districts were harmonized to {N['n_districts']} units with 2024 boundaries, giving {N['n_rows']:,} district-years. Mid-year resident registration populations by 5-year age group were used as denominators [@web:mois2026population]; the 2023 age block of one city (Changwon), which duplicated the 2022 block in the source file, was replaced with official totals and a residual reconstruction (Supplemental Material, Supplementary Methods)."),
("Age standardization",
 "Expected counts were obtained by indirect standardization: national age-specific treatment rates for the same diagnoses in ten age groups (0-9 to 50-59 years in 10-year groups, 60-64, 65-69, 70-74, and 75 years or older, the finest grouping available in every year) were applied to each district's age structure, and expected counts were rescaled each year to the observed national total [@inskip1983methods]. The ratio of observed to expected counts is the standardized treatment ratio (STR); because national rates were rescaled annually, each STR is relative to the national treatment pattern of the same year, and indirectly standardized ratios retain district-specific age weights. National trends were summarized by direct standardization to the 2015 national population in the same age groups. National treatment tables are not published by sex, so standardization was by age only."),
("Covariates",
 f"Before the age-standardized models were fitted, {N['n_hyp']} district characteristics were specified from the literature with an expected direction (recorded on 19 October 2026 and archived with the code; the protocol was not registered): physical activity and its environment (walking and moderate-or-vigorous physical activity from the Community Health Survey [@kang2015korea], densities of public sports facilities, community gyms, and village sports facilities per 100,000 population, green area share, and registered cars per capita), cardiometabolic behaviors (the share of screened adults classified as normal-B for obesity at national health screening, that is, needing obesity management, current smoking, high-risk drinking, perceived stress, good self-rated health, and nutrition label use), detection (health screening uptake), and social structure (older single-person households, employment rate, and regular employment). Other measures of hypertension itself were excluded. Public sports facilities were all registered public facilities, including stadiums, gyms, swimming pools, and outdoor courts. Five controls were forced into every model: urban population share, clinic density, sex ratio, fiscal independence, and the share of the population aged 80 years or older, because the oldest standardization group (75 years or older) cannot capture differences in very old age within it. Covariates were standardized to 1 standard deviation (SD). Missing district-years were filled within districts (Supplemental Material, Table S1)."),
("Statistical analysis",
 "Counts were modeled with a negative binomial likelihood, an offset of log expected counts, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@riebler2016intuitive], and first-order random-walk and independent year effects, using integrated nested Laplace approximation (R-INLA in R 4.6.0) [@rue2009approximate]. District adjacency was defined by shared polygon boundaries, with six island districts linked to their nearest neighbor; Jeju Island formed a separate component. This model was prespecified as the principal model; models with space-time interactions were treated as sensitivity analyses because interaction terms absorb district-specific trends together with part of the covariate variation. Rate ratios (RRs) per 1 SD were judged credible when 95% credible intervals (CrIs) excluded 1; with 17 hypothesis covariates, about one credible association could arise by chance. Model fit was compared with the widely applicable information criterion (WAIC). Robustness to covariate selection was assessed in a covariate-subset sensitivity analysis adapted from multiverse analysis [@steegen2016increasing]: 200 random subsets of the hypothesis covariates were each fitted with all forced controls, and a covariate was classed as subset-stable if credible in at least 75% of subsets containing it with the same sign in at least 95% (study-defined, descriptive thresholds). Covariate-adjusted hot and cold spots were districts with a posterior probability of a residual RR above 1 of more than 0.95 or less than 0.05, estimated for the full period and for three calendar windows (2011-2015, 2016-2019, 2020-2024). The north-south gradient was assessed by Spearman correlation of district centroid northing with residual RRs and with empirical Bayes-smoothed STRs without covariates. Persistence was summarized by Kendall's W of annual rankings of unsmoothed STRs and by emerging hot spot analysis (Getis-Ord Gi* with Mann-Kendall trends) of empirical Bayes-smoothed ratios [@getis1992analysis; @mann1945nonparametric]."),
("Sensitivity analyses",
 "Knorr-Held type I-IV space-time interactions were added to the principal model, with sum-to-zero constraints defined for each connected component of the adjacency graph [@knorrheld2000bayesian]. Subset-stable covariates were decomposed into district means and two-way-centered within-district deviations [@bell2015explaining]. Further analyses varied the likelihood, time effects, priors, neighborhoods, adjustment for spatial confounding [@hodges2010adding; @dupont2022spatial], lags, provinces and years included, imputed values, adjacency corrections, age grouping, and the oldest-age control (Supplemental Material, Supplementary Methods and Tables S2-S4). Treated gastric cancer and infectious diseases served as comparison outcomes, and fires, multicultural marriages, and rear-seat belt wearing as negative-control exposures, chosen because they share socioeconomic, demographic, or behavioral confounding with district health but have no plausible causal path to hypertension care [@lipsitch2010negative]. E-values quantified the confounding needed to explain each association [@vanderweele2017sensitivity], and posterior predictive checks assessed fit; for the held-out check, 2024 counts were predicted from a model fitted to 2011-2023 with district counts conditional on the observed 2024 national total. Reporting follows the Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) and Reporting of studies Conducted using Observational Routinely-collected health Data (RECORD) statements [@vonelm2007strengthening; @benchimol2015reporting] (checklist in the Supplemental Material). The author used Claude (Anthropic) and ChatGPT (OpenAI) only for translation and English-language editing of the manuscript."),
]

_hot_all = N["hot_all_windows"]; tc = N["type_class"]
def sido_frac(cls, ko):
    import pandas as _p
    s6 = _p.read_csv(os.path.join(RS, "S6_spatial_RR.csv")); s = s6[s6.fbd_region.str.startswith(ko)]
    return f"{int((s['class'] == cls).sum())} of {len(s)}"
RESULTS = [
("Treated persons and trends",
 f"Over 2011-2024, {N['cases_total']/1e6:.1f} million treated person-years were recorded among {N['py']/1e6:.0f} million person-years (Supplemental Material, Table S5). The crude treatment rate rose from {N['crude_2011']:,.0f} to {N['crude_2024']:,.0f} per 100,000 population ({100*(N['crude_2024']/N['crude_2011']-1):.0f}% increase), whereas the directly age-standardized rate (2015 standard population) was {N['asr_2011']:,.0f} in 2011 and {N['asr_2024']:,.0f} in 2024 (Figure 1). The 10th-90th percentile range of district STRs was {T1['2011-2024']['sir_p10']:.2f}-{T1['2011-2024']['sir_p90']:.2f}."),
("Spatial pattern and persistence",
 f"Moran's I of the log STR was {N['moran_pooled']:.2f} for the pooled period and {N['moran_year_min']:.2f}-{N['moran_year_max']:.2f} by year, without a trend; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}-{N['phi'][2]:.2f}). Residual RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, mainly in {sidos(N['hot_by_sido'], 6)}, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 6)} (Figure 1). Residual RRs were correlated with district northing (Spearman ρ {N['lat_rr']:.2f}), as were empirical Bayes-smoothed STRs without covariates (ρ {N['lat_eb']:.2f}), and the two measures were closely correlated with each other (ρ {N['rr_eb']:.2f}). Hot spots comprised {tc['hotspot']['city']} cities, {tc['hotspot']['county']} rural counties, and {tc['hotspot']['ward']} urban wards, and cold spots {tc['coldspot']['ward']} wards, {tc['coldspot']['county']} counties, and {tc['coldspot']['city']} cities. In all three separately fitted window models, {_hot_all} districts were hot spots (listed in the Supplemental Material) and {N['cold_all_windows']} were cold spots (Figure 2). District rankings were stable (Kendall's W {N['kendall_W']:.2f}; {N['kendall_W_2024']:.2f} in 2020-2024). Emerging hot spot analysis classified {N['ehsa']['No pattern']} districts as having no trend pattern (Figure 2)."),
("District correlates in the principal model",
 f"Adding the {N['n_hyp']} covariates improved fit over the forced controls alone (ΔWAIC {N['waic_main']-N['waic_forced']:.0f}). In the principal model, {N['n_cred_hyp']} of {N['n_hyp']} covariates were credible, and all {N['n_robust']} were subset-stable (Table 1). Per 1 SD, treatment was lower where public sports facilities were denser ({ci('public_sports_facilities_per_100k')}) and where walking ({ci('walking_practice_rate')}) and moderate physical activity ({ci('moderate_pa_rate')}) were more common, and higher with a larger share of screened adults needing obesity management ({ci('screening_normalB_obesity_share')}) and more high-risk drinking ({ci('high_risk_drinking_rate')}). Among forced controls, the share aged 80 years or older ({ci('pop80_share')}), sex ratio ({ci('sex_ratio')}), and fiscal independence ({ci('fiscal_independence')}) were positively associated and clinic density inversely ({ci('clinics_per_100k')})."),
("Space-time interaction and other sensitivity analyses",
 f"Knorr-Held type II and IV interactions, which allow district-specific trends, fitted much better than the principal model (ΔWAIC {dW('KH_typeII'):,.0f} and {dW('KH_typeIV'):,.0f}). Public sports facilities remained credibly associated in all four interaction models (type II {tci(S43('KH_typeII','public_sports_facilities_per_100k'))}; type IV {tci(S43('KH_typeIV','public_sports_facilities_per_100k'))}), and obesity management in types I-III but not IV ({tci(S43('KH_typeIV','screening_normalB_obesity_share'))}). Walking, moderate physical activity, and high-risk drinking remained credible only in type I (type IV walking {tci(S43('KH_typeIV','walking_practice_rate'))}; moderate physical activity {tci(S43('KH_typeIV','moderate_pa_rate'))}; drinking {tci(S43('KH_typeIV','high_risk_drinking_rate'))}) (Figure 3). In the type IV model, four covariates that were not credible in the principal model became credible: village sports facilities ({tci(S43('KH_typeIV','village_sports_facilities_per_100k'))}), registered cars ({tci(S43('KH_typeIV','cars_per_capita'))}), older single-person households ({tci(S43('KH_typeIV','older_single_household_share'))}), and urban population share ({tci(S43('KH_typeIV','urban_population_share'))}) (Table 1). "
 f"When decomposed, all five covariates had credible within-district components (public sports facilities {tci(N['bw']['public_sports_facilities_per_100k__within'])}); between-district components were not credible (public sports facilities {tci(N['bw']['public_sports_facilities_per_100k__between'])}) except for high-risk drinking ({tci(N['bw']['high_risk_drinking_rate__between'])}). Retention of the five covariates across alternative specifications, leave-one-out fits, and perturbed imputed values is reported in the Supplemental Material (Additional results; Tables S2 and S3). Results were unchanged with the alternative adjacency graph and eight-group expected counts, but without the share aged 80 years or older the association with public sports facilities was no longer credible ({tci(SC('s2','public_sports_facilities_per_100k'))}); it was also not credible in a model without a district effect ({tci(S43('no_spatial','public_sports_facilities_per_100k'))}). "
 f"For the comparison outcomes, public sports facilities were not credibly associated with infectious diseases ({tci(NCO('INFECT','public_sports_facilities_per_100k'))}) or gastric cancer ({tci(NCO('GCA','public_sports_facilities_per_100k'))}); obesity management had an RR below 1 for gastric cancer ({tci(NCO('GCA','screening_normalB_obesity_share'))}), and high-risk drinking had RRs below 1 for infectious diseases ({tci(NCO('INFECT','high_risk_drinking_rate'))}) and gastric cancer ({tci(NCO('GCA','high_risk_drinking_rate'))}). One of three negative-control exposures was credible (multicultural marriages {tci(NC('multicultural_marriage_share'))}). Posterior predictive checks and residual spatial autocorrelation are reported in the Supplemental Material (Table S4)."),
]

if __name__ == "__main__":
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")


